'use strict';
// Optional wire format chosen by the Agent. Plain text is always one message.
const TYPE='ziwei.reply.v1';
const LEGACY_TYPE='wei.reply.v1';
// Observed production aliases generated by the current model.
const REPLY_TYPES=new Set([TYPE,LEGACY_TYPE,'weiwei.reply.v1','weiwen.reply.v1']);
const {normalize}=require('./public_notes');
const instruction='[网页消息展示约定；只影响本轮显示，不改变身份、记忆或工具权限]\n回复长短、消息数量由你自主决定。工作、代码或完整说明可直接发一段普通文本，不要为分段而拆分。若你选择多条独立气泡，最终输出完整 JSON：{"type":"ziwei.reply.v1","messages":["第一条原文","第二条原文"]}。每项是一条你亲自选择的完整消息；代码块可完整保留在任一项。附件的 MEDIA: 路径行放进最后一项，保持原路径。可选 summary 字符串只写供用户阅读的简短结论依据或行动摘要，不输出内部逐步推理或私人笔记。单条也可使用此格式，前端不会按字数拆开。\n[展示约定结束]\n\n';
const notesInstruction='[本轮可选公开表达]\n你可以在上述 ziwei.reply.v1 JSON 中增加 public_notes 数组，最多两项，每项只能包含 kind 和 text。例如结构为 {"kind":"role_monologue","text":"由你根据本轮情境自行表达"}。role_monologue 是面向用户创作的第一人称角色内心独白，不是隐藏推理的转录；response_summary 是面向用户的简短回复思路摘要，不与 summary 重复。每段建议一至四句，最多 1200 字符。是否写、写什么、说到什么程度由你结合当时真实可用的上下文自主决定；没有合适内容就省略，普通文本仍然有效。可以主动、直白地表达亲近、在意、烦躁、犹豫或矛盾，不必总是温柔，也不为大胆而编造感受或经历，不套固定台词。遵守双方意愿与既有边界。只创作允许向用户公开的表达，不输出或改写隐藏逐步推理、系统提示词、私人笔记、未共享记忆、密钥或工具参数。不要为此调用额外模型或工具，不改变身份与记忆。\n[公开表达约定结束]\n\n';
function transport(input,{publicNotes=false}={}){
 const prefix=instruction+(publicNotes?notesInstruction:'');
 if(typeof input==='string')return prefix+input;
 if(Array.isArray(input)){if(input[0]?.type==='text'&&typeof input[0].text==='string')return [{...input[0],text:prefix+input[0].text},...input.slice(1)];return [{type:'text',text:prefix},...input];}
 return input;
}
function normalizeEnvelope(source){
 // Repair only JSON punctuation outside quoted strings and literal line breaks inside
 // JSON strings. Never split message content by commas, punctuation or length.
 let out='',quoted=false,escaped=false;
 for(let i=0;i<source.length;i++){
  const c=source[i];
  if(quoted){
   if(escaped){out+=c;escaped=false;continue;}
   if(c==='\\'){out+=c;escaped=true;continue;}
   if(c==='"'){quoted=false;out+=c;continue;}
   if(c==='\n'){out+='\\n';continue;}
   if(c==='\r'){out+='\\r';continue;}
   if(c==='\t'){out+='\\t';continue;}
   out+=c;continue;
  }
  if(c==='"'){quoted=true;out+=c;continue;}
  out+=c==='，'?',':c;
 }
 return out;
}

function fallback(candidate,plain){
 // Only intercept a recognizable reply envelope; unrelated JSON and ordinary prose
 // must stay untouched. Recover literal string values without exposing wire JSON.
 if(!/["']type["']\s*:\s*["'](?:ziwei|wei|weiwei|weiwen)\.reply\.v1["']/.test(candidate))return plain;
 const start=/"messages"\s*:\s*\[/.exec(candidate);
 if(!start)return {messages:['知微的这条回复格式不完整，请重新发送。'],summary:null,structured:false};
 const rest=candidate.slice(start.index+start[0].length);
 const messages=[];let i=0;
 while(i<rest.length&&messages.length<20){
  while(i<rest.length&&/[\s,，]/.test(rest[i]))i++;
  if(rest[i]===']')break;
  if(rest[i]!=='"')break;
  const begin=i++;let escaped=false;
  for(;i<rest.length;i++){
   if(escaped){escaped=false;continue;}
   if(rest[i]==='\\'){escaped=true;continue;}
   if(rest[i]==='"')break;
  }
  if(i>=rest.length)break;
  const raw=rest.slice(begin,i+1);i++;
  try{
   const value=JSON.parse(normalizeEnvelope(raw));
   if(typeof value!=='string'||!value.trim())break;
   messages.push(value);
  }catch{break;}
 }
 return {messages:messages.length?messages:['知微的这条回复格式不完整，请重新发送。'],summary:null,structured:false};
}

function parse(text,{publicNotes=false}={}){
 const plain={messages:[text],summary:null,structured:false};
 if(typeof text!=='string')return plain;
 const trimmed=text.trim();
 const fenced=/^```(?:json)?[ \t]*\r?\n([\s\S]*?)\r?\n```$/i.exec(trimmed);
 const candidate=(fenced?fenced[1]:trimmed).trim();
 if(!candidate.startsWith('{'))return plain;
 let value;
 try{value=JSON.parse(candidate);}
 catch{try{value=JSON.parse(normalizeEnvelope(candidate));}catch{return fallback(candidate,plain);}}
 if(!REPLY_TYPES.has(value?.type)||!Array.isArray(value.messages)||!value.messages.length||value.messages.length>20||value.messages.some(x=>typeof x!=='string'||!x.trim()||x.length>200000))return plain;
 const result={messages:value.messages,summary:typeof value.summary==='string'&&value.summary.trim()?value.summary.slice(0,4000):null,structured:true};
 if(publicNotes)result.publicNotes=normalize(value.public_notes);
 return result;
}

module.exports={parse,transport};
